// Filtro de seguridad del bot (ataque A2): se valida el chat y se bloquea
// cualquier texto con sintaxis SQL ANTES de llegar a la base de datos.
const data = $getWorkflowStaticData('global');
const updates = $json.result || [];
const permitidos = __TELEGRAM_CHATS_PERMITIDOS__;
const patronSQL = /(;|--|\/\*|\*\/|'|"|\b(drop|delete|insert|update|alter|truncate|union|select|grant|revoke|create|exec|execute|copy|pg_sleep|information_schema|pg_catalog)\b)/i;
const salida = [];
for (const u of updates) {
  if (!data.lastUpdateId || u.update_id > data.lastUpdateId) data.lastUpdateId = u.update_id;
  const msg = u.message || u.edited_message;
  if (!msg || !msg.text || !msg.chat) continue;
  if (!permitidos.includes(msg.chat.id)) continue;
  const texto = msg.text.trim().slice(0, 500);
  const coincidencia = texto.match(patronSQL);
  const t = texto.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  let reporte = 'ayuda';
  if (coincidencia) reporte = 'bloqueado';
  else if (t.includes('venta')) reporte = 'ventas';
  else if (t.includes('inventario') || t.includes('materia')) reporte = 'inventario';
  else if (t.includes('produccion') || t.includes('lote')) reporte = 'produccion';
  salida.push({ json: {
    update_id: u.update_id,
    chat_id: msg.chat.id,
    usuario: msg.from?.username || msg.from?.first_name || 'desconocido',
    usuario_id: msg.from?.id ?? null,
    texto,
    reporte,
    patron: coincidencia ? coincidencia[0] : null
  }});
}
return salida;

